package ama.transcript;
import java.util.*;import ama.contract.TaskContracts.*;import ama.contract.MinutesContracts.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class Task10Fix01DomainCapacityTest {
 Map<String,List<Map<String,Object>>> rows(){var r=new HashMap<String,List<Map<String,Object>>>();for(String f:MinutesDomainCapacity.FAMILIES)r.put(f,new ArrayList<>());return r;}
 void task(Map<String,List<Map<String,Object>>> r,String id,String type,String state,int attempt){r.get("durable_task").add(Map.of("id",id,"task_type",type,"producer_key",id,"input_id",id,"state",state,"attempt",(long)attempt,"max_attempts",3L));if(type.equals("MINUTES_GENERATE_V1"))r.get("generation_input").add(Map.of("id",id));for(int n=1;n<=attempt;n++)r.get("task_attempt").add(Map.of("task_id",id,"attempt",(long)n));}
 TaskSpec next(String type){String id=UUID.randomUUID().toString();return new TaskSpec(type,type.equals("MINUTES_GENERATE_V1")?"MINUTES_GENERATE":"TRANSCRIPT_IMPORT",new SubjectRef("MEETING",UUID.randomUUID().toString()),"a".repeat(64),new TypedRef(type.equals("MINUTES_GENERATE_V1")?"GENERATION_INPUT":"TRANSCRIPTION_INPUT",id),"b".repeat(64),1,0,0,3);}
 @Test void lastAttemptSlotIncludesRetainedSourceAndAllRemainingClaims(){var r=rows();task(r,"source","TRANSCRIPT_IMPORT_V1","SUCCEEDED",1);for(int n=0;n<84;n++)task(r,"gen"+n,"MINUTES_GENERATE_V1","READY",0);var spec=next("MINUTES_GENERATE_V1");assertEquals(256L,MinutesDomainCapacity.reserve(r,256,256,spec).get("task_attempt"));task(r,"last","MINUTES_GENERATE_V1","RUNNING",1);assertEquals(256L,MinutesDomainCapacity.reserve(r,256,256,null).get("task_attempt"));assertEquals(FailureCode.BUDGET_EXCEEDED,assertThrows(Failure.class,()->MinutesDomainCapacity.reserve(r,256,256,spec)).code());}
 @Test void consumedAttemptNotDoubleCountedAndTerminalHistoryRemains(){var r=rows();task(r,"active","MINUTES_GENERATE_V1","RUNNING",2);task(r,"old","MINUTES_GENERATE_V1","FAILED",1);task(r,"observed","MINUTES_GENERATE_V1","RECONCILING",1);var n=MinutesDomainCapacity.reserve(r,256,256,null);assertEquals(5L,n.get("task_attempt"));assertEquals(2L,n.get("external_execution"));assertEquals(2L,n.get("generation_candidate"));var merged=MinutesDomainCapacity.merge(r,r);assertEquals(n,MinutesDomainCapacity.reserve(merged,256,256,null));}
 @Test void sourceAdmissionReservesOnlyRealLocalAttemptFootprint(){var r=rows();var n=MinutesDomainCapacity.reserve(r,1,256,next("TRANSCRIPT_IMPORT_V1"));assertEquals(1L,n.get("durable_task"));assertEquals(3L,n.get("task_attempt"));for(String table:List.of("generation_input","generation_candidate","external_operation","external_execution"))assertEquals(0L,n.get(table));task(r,"source","TRANSCRIPT_IMPORT_V1","SUCCEEDED",1);assertThrows(Failure.class,()->MinutesDomainCapacity.reserve(r,1,256,next("MINUTES_GENERATE_V1")));}
 @Test void explicitLegacyOverflowNeverTruncates(){var r=rows();for(int n=0;n<86;n++)task(r,"old"+n,"MINUTES_GENERATE_V1","FAILED",3);assertEquals(258,r.get("task_attempt").size());assertEquals(FailureCode.BUDGET_EXCEEDED,assertThrows(Failure.class,()->MinutesDomainCapacity.reserve(r,256,256,null)).code());assertEquals(258,r.get("task_attempt").size());}
 @Test void existingExternalAndCandidateRowsConsumeTheirReservationOnce(){var r=rows();task(r,"g","MINUTES_GENERATE_V1","RECONCILING",1);r.get("external_operation").add(Map.of("id","op","business_key","minutes:g"));r.get("external_execution").add(Map.of("id","ex","task_id","g"));r.get("generation_candidate").add(Map.of("id","c","task_id","g"));var n=MinutesDomainCapacity.reserve(r,256,256,null);for(String table:List.of("external_operation","external_execution","generation_candidate"))assertEquals(1L,n.get(table));}
}
